int i2c_addr()
{
    return 0x38;		// 7-bit I2C slave address
}
void setup()
{
    setWAKE(0);			// set reset pin to low
    delay_ms(10);		// wait for 10ms
    setWAKE(1);			// set reset pin to high
    delay_ms(300);		// wait for 300ms
}
void rtouch()
{
    int x = i2c_read16be() &amp; 0xfff;	// read 12-bit X value
    int id_y = i2c_read16be();		// read id and 12-bit Y value
    i2c_read8();			// read 1 byte
    i2c_read8();
    report_touch(id_y &gt;&gt; 12, x, id_y &amp; 0xfff);	// report id, X and Y values
    // should be disabled during the production phase to optimize performance
    printf(&quot;DbgMsg: x-axis = %d y-axis = %d\n&quot;, x, id_y);
}
void loop()
{
    while (getINT() == 1)		 // wait for INT to go low
        ;
    i2c_startread(0x02);		 // start I2C read cycle
    int n_touches = i2c_read8();	 // read number of touch points
    while (n_touches != 0)
    {
        rtouch();
        n_touches = n_touches - 1;
    }
    i2c_stop();				 // end I2C read cycle
    while (getINT() == 0) 		 // wait for INT to go high
        ;
}

ilitek.code:
int i2c_addr()
{
    return 0x41;		// 7-bit I2C slave address
}
void setup()
{
    setWAKE(0);
    delay_ms(30);
    setWAKE(1);
    delay_ms(300);
}
void loop()
{
    while (getINT() == 1) 	// wait for INT to go low
        ;
    i2c_startread(0x10);	// start I2C read cycle
    i2c_read8();		// read 1 byte
    int id = 0;
    int event_x;
    int y;
    while (id &lt; 5)    			// 1..5, support up to 5 touches
    {
        event_x = i2c_read16be();   	// read event and 15-bit X value
        y = i2c_read16be();		// read 15-bit Y value
        i2c_read8();			// read 1 byte
        if ((event_x &amp; 0x8000) == 0x8000)    // pressed
        {
            report_touch(id, event_x &amp; 0x7fff, y &amp; 0x7fff);   // report id, X and Y values
        }
        id = id + 1;
    }
    y = 0;
    while (y &lt; (64-id*5-1))	// read the remaining bytes of a report
    {
        i2c_read8();
        y = y + 1;
    }
    i2c_stop();			// end I2C read cycle
    while (getINT() == 0) 	// wait for INT to go high
        ;
}

